package com.greenlogreorder;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class GreenLogReorderPluginTest
{
	public static void main(String[] args) throws Exception
	{
		// Isolate the dev client to its own RuneLite home BEFORE any RuneLite class loads
		// (RuneLite.RUNELITE_DIR is derived from user.home at class-init time). Without this,
		// gradlew run would also load any Plugin Hub copy of this plugin from ~/.runelite.
		java.io.File devHome = new java.io.File(System.getProperty("user.dir"), "build/runelite-dev");
		//noinspection ResultOfMethodCallIgnored
		devHome.mkdirs();
		System.setProperty("user.home", devHome.getAbsolutePath());
		System.out.println("[dev] isolated RuneLite home: " + devHome.getAbsolutePath());

		ExternalPluginManager.loadBuiltin(GreenLogReorderPlugin.class);
		RuneLite.main(args);
	}
}

package com.greenlogreorder;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.Predicate;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.Text;

/**
 * Reorders the in-game Collection Log and the Combat Achievements boss list so the things you still
 * need float to the top, while every record stays visible (nothing is hidden):
 * <ul>
 *   <li><b>Items</b> — on each collection log page, un-obtained (faded) items are kept first and
 *       obtained items are moved to the bottom of the grid.</li>
 *   <li><b>Categories</b> — in each collection log tab's left-side list, pages with pending items
 *       are kept first and fully-completed ("green") pages are moved to the bottom.</li>
 *   <li><b>Combat achievement bosses</b> — in the boss selection grid, bosses that still have tasks
 *       left are kept first and fully-completed ("green") bosses are moved to the bottom.</li>
 * </ul>
 *
 * <p>The game itself already encodes completion in the widgets — obtained items render at full
 * opacity ({@code opacity == 0}) while un-obtained ones are faded, and a fully-completed category
 * or boss name is drawn in the game's "completed" green ({@link #COMPLETED_PAGE_COLOR}). We read
 * that visual state directly, so no collection-log syncing or task data is needed.
 *
 * <h3>Three different techniques, because the three surfaces work differently</h3>
 * <b>Items</b> are plain icons with no navigation, so we physically reorder them: each pass drops
 * the icons back into the cells they already occupy ({@code setOriginalX/Y} + {@code revalidate}),
 * in the desired order. Extent is preserved, so scroll geometry is untouched.
 *
 * <p><b>Categories</b> can't be reordered that way. The clickable hit-target is a separate
 * rectangle layer (e.g. {@code BOSS_BACKGROUND} 621:11), and a click routes by the clicked entry's
 * <i>child index</i> (= the page's original order), not by the label or screen position. Moving the
 * label layer (621:12) would desync the labels from where clicks route. So instead we
 * <b>relabel in place</b>: each slot's text+color is overwritten to display the page we want shown
 * there, and the click is <b>remapped</b> in {@link #onMenuOptionClicked} so it opens the page the
 * label represents.
 *
 * <p><b>Combat achievement bosses</b> get a third technique: we <b>move whole cells</b>. A boss cell
 * is stacked out of nine layers with differing child counts, so each part is matched to its cell by
 * position and translated to the destination cell (see {@link #layoutCaBosses}). No relabelling and
 * no click remap are needed here — the draw proc bakes each boss's own index into that cell's onOp
 * args, so a moved cell still opens its own boss.
 *
 * <p>The draw scripts ({@value #COLLECTION_LOG_DRAW_LIST_SCRIPT} and
 * {@value #CA_BOSSES_DRAW_LIST_SCRIPT}) rebuild the children to their natural order on every open /
 * page switch / tab switch / search, so we re-apply on every fire, <b>synchronously</b> in the
 * {@link ScriptPostFired} handler (which already runs on the client thread). We do NOT call
 * {@code client.runScript(...)} here — running a cs2 script from inside a script event throws
 * "scripts are not reentrant".
 */
@Slf4j
@PluginDescriptor(
	name = "Green Reorder",
	description = "Reorders the collection log and the combat achievements boss list so uncompleted entries come first; completed (green) ones drop to the bottom",
	tags = {"collection", "log", "clog", "combat", "achievements", "ca", "tasks", "reorder", "sort", "pending", "obtained"}
)
public class GreenLogReorderPlugin extends Plugin
{
	// The cs2 script that draws/redraws a collection log page and its category list. Fires on the
	// first open and on every page/tab switch (net.runelite.api.ScriptID.COLLECTION_DRAW_LIST).
	private static final int COLLECTION_LOG_DRAW_LIST_SCRIPT = 2731;

	// Collection log interface group (InterfaceID.COLLECTION).
	private static final int COLLECTION_LOG_GROUP = 621;

	// Right-side item panel: the scrollable content container holding the item icons.
	private static final int ITEMS_CONTENTS_CHILD = 37;  // InterfaceID.Collection.ITEMS_CONTENTS

	// Left category list — the scrollable *text label* layer per tab (one is visible at a time).
	// Names per gameval InterfaceID.Collection.*_TEXT. (621:32 / 621:34 are *_BACKGROUND layers.)
	private static final int[] CATEGORY_TEXT_CHILDREN = {
		12, // BOSS_TEXT
		16, // RAID_TEXT
		33, // CLUE_TEXT
		36, // MINIGAME_TEXT
		35, // OTHER_TEXT
	};

	// The game's "fully completed" green, used on collection log category names and on combat
	// achievement boss names (0x0DC10D).
	private static final int COMPLETED_PAGE_COLOR = 901389;

	// The left-click op on a category entry (cc_setop(1, "Check")).
	private static final String CATEGORY_OP = "Check";

	// Item rows have an item id; un-obtained items are faded (opacity != 0), obtained ones opaque (0).
	private static final Predicate<Widget> ITEM_ROW = w -> w.getItemId() > 0;
	private static final Predicate<Widget> ITEM_PENDING = w -> w.getOpacity() != 0;

	// The cs2 proc that draws the Combat Achievements boss grid ([proc,ca_bosses_draw_list]). Fires
	// when the boss list opens and on every search/refresh, rebuilding it in its natural order.
	private static final int CA_BOSSES_DRAW_LIST_SCRIPT = 4800;

	// Combat Achievements boss-select interface group (InterfaceID.CA_BOSSES).
	private static final int CA_BOSSES_GROUP = 716;

	// The scrollable container holding the boss grid (InterfaceID.CaBosses.BOSSES_LIST).
	private static final int CA_BOSSES_LIST_CHILD = 10;

	// The per-boss name labels (InterfaceID.CaBosses.BOSSES_NAME): exactly one child per drawn boss,
	// created in natural order, drawn in the completed green when all of that boss's tasks are done.
	// Used as the grid anchor — the cells its children sit in *are* the grid.
	private static final int CA_BOSSES_NAME_CHILD = 14;

	// Every layer the draw proc fills with per-boss parts. Most hold one child per boss, but
	// BOSSES_PROGRESS only gets a bar for bosses that have tasks, so a child's index says nothing
	// about which boss it belongs to — parts are matched to cells by position instead.
	// BOSSES_NONE (716:20) is left out: it's the "no results" placeholder, not a per-boss part.
	private static final int[] CA_BOSSES_CELL_CHILDREN = {
		11, // BOSSES_BUTTON
		12, // BOSSES_BUTTON_CLICK
		13, // BOSSES_BACKGROUND
		14, // BOSSES_NAME
		15, // BOSSES_BUTTON_CLICK_PAUSE
		16, // BOSSES_MONSTER
		17, // BOSSES_DESCRIPTION
		18, // BOSSES_ICON
		19, // BOSSES_PROGRESS
	};

	// Grid spacing from [proc,ca_bosses_draw_list]: 3 columns of 145x88 cells at x = 5 + col * 150,
	// y = row * 93. Only a fallback for when a one-row / one-column grid gives nothing to measure.
	private static final int CA_CELL_COLUMNS = 3;
	private static final int CA_CELL_PITCH_X = 150;
	private static final int CA_CELL_PITCH_Y = 93;

	// v1.1.0 briefly replaced the per-list checkboxes with one multi-select stored under this key, as
	// a JSON array of enum names. Read once at start-up to put the checkboxes back the way that
	// version left them (see migrateSurfacesToToggles).
	private static final String SURFACES_KEY = "surfaces";
	private static final String[] SURFACE_NAMES = {"ITEMS", "CATEGORIES", "CA_BOSSES"};
	private static final String[] TOGGLE_KEYS = {"reorderItems", "reorderPages", "reorderCombatAchievements"};

	private static final Comparator<Widget> BY_POSITION =
		Comparator.comparingInt(Widget::getOriginalY).thenComparingInt(Widget::getOriginalX);

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private GreenLogReorderConfig config;

	@Inject
	private ConfigManager configManager;

	// State for the currently-relabeled category list (active tab), recomputed on each draw.
	// pagePerm[slot] = the original page index displayed at that slot (used to remap clicks).
	private volatile int[] pagePerm;
	private String[] pageNaturalText;   // child i -> the page name the game drew there
	private int[] pageNaturalColor;     // child i -> the text color the game drew there
	private int pageListChild = -1;     // which CATEGORY_TEXT_CHILDREN layer we relabeled

	@Provides
	GreenLogReorderConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GreenLogReorderConfig.class);
	}

	@Override
	protected void startUp()
	{
		migrateSurfacesToToggles();
		clientThread.invokeLater(() ->
		{
			applyReorder();
			return true;
		});
	}

	/**
	 * Sets the per-list checkboxes from whichever lists were selected in the multi-select that
	 * v1.1.0 shipped, so a list someone had deselected there doesn't silently come back on.
	 *
	 * <p>Only v1.1.0 wrote {@code surfaces}, and it deleted the checkbox keys when it did, so its
	 * value is the only remaining record of that choice. Anyone who never ran v1.1.0 has no
	 * {@code surfaces} entry and still has their original checkbox values, which need no migration.
	 *
	 * <p>Triggered by the presence of {@code surfaces} rather than the absence of the checkbox keys:
	 * RuneLite writes a config item's default into the store as soon as the plugin's config is
	 * registered, which happens before {@code startUp}, so the checkboxes are always set by now.
	 * {@code surfaces} is removed once read, and nothing declares it any more, so this runs once.
	 *
	 * <p>The stored value is parsed as bare enum names rather than deserialised, so the enum itself
	 * doesn't have to be kept around just to read one obsolete key.
	 */
	private void migrateSurfacesToToggles()
	{
		String stored = configManager.getConfiguration(GreenLogReorderConfig.GROUP, SURFACES_KEY);
		if (stored == null)
		{
			return;
		}

		// e.g. ["ITEMS","CA_BOSSES"] -> the set {ITEMS, CA_BOSSES}. Names are upper case with
		// underscores, so everything else is a separator.
		Set<String> selected = new HashSet<>(Arrays.asList(stored.replaceAll("[^A-Z_]+", " ").trim().split(" ")));
		for (int i = 0; i < TOGGLE_KEYS.length; i++)
		{
			configManager.setConfiguration(GreenLogReorderConfig.GROUP, TOGGLE_KEYS[i], selected.contains(SURFACE_NAMES[i]));
		}
		configManager.unsetConfiguration(GreenLogReorderConfig.GROUP, SURFACES_KEY);
		log.debug("Migrated the v1.1.0 multi-select {} back to the per-list checkboxes", selected);
	}

	@Override
	protected void shutDown()
	{
		clientThread.invokeLater(() ->
		{
			restoreNaturalOrder();
			return true;
		});
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		int script = event.getScriptId();
		if (script == COLLECTION_LOG_DRAW_LIST_SCRIPT || script == CA_BOSSES_DRAW_LIST_SCRIPT)
		{
			// Apply synchronously (already on the client thread) so the reordered view is what gets
			// drawn this frame — deferring would flash the default order for one tick.
			// Running the whole pass for either script is harmless: each half bails out when its own
			// interface isn't loaded.
			applyReorder();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!GreenLogReorderConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		clientThread.invokeLater(() ->
		{
			restoreNaturalOrder();
			applyReorder();
			return true;
		});
	}

	/**
	 * Remaps a click on a (visually relabeled) category entry to the page its label represents.
	 * The click routes by child index ({@code param0}); we rewrite it to the original index of the
	 * page currently shown at that slot, then let the normal action proceed.
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		int[] perm = pagePerm;
		if (perm == null)
		{
			return;
		}
		MenuAction action = event.getMenuAction();
		if (action != MenuAction.CC_OP && action != MenuAction.CC_OP_LOW_PRIORITY)
		{
			return;
		}
		if ((event.getParam1() >>> 16) != COLLECTION_LOG_GROUP)
		{
			return;
		}
		if (!CATEGORY_OP.equalsIgnoreCase(Text.removeTags(event.getMenuOption())))
		{
			return;
		}
		int slot = event.getParam0();
		if (slot < 0 || slot >= perm.length)
		{
			return;
		}
		int target = perm[slot];
		if (target != slot)
		{
			event.getMenuEntry().setParam0(target);
		}
	}

	private void applyReorder()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		if (config.reorderItems())
		{
			layout(ITEMS_CONTENTS_CHILD, ITEM_ROW, ITEM_PENDING, false);
		}
		if (config.reorderPages())
		{
			reorderPages();
		}
		else
		{
			clearPageState();
		}
		if (config.reorderCombatAchievements())
		{
			layoutCaBosses(false);
		}
	}

	private void restoreNaturalOrder()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		layout(ITEMS_CONTENTS_CHILD, ITEM_ROW, ITEM_PENDING, true);
		restorePages();
		layoutCaBosses(true);
	}

	// --- Categories: relabel the active tab's list in place (pending pages first). ---

	private void reorderPages()
	{
		int child = activeCategoryListChild();
		if (child < 0)
		{
			clearPageState();
			return;
		}
		Widget list = client.getWidget(COLLECTION_LOG_GROUP, child);
		Widget[] rows = list == null ? null : list.getDynamicChildren();
		if (rows == null || rows.length < 2)
		{
			clearPageState();
			return;
		}

		// The game has just (re)built the list in its natural order: child i = page i.
		int n = rows.length;
		String[] names = new String[n];
		int[] colors = new int[n];
		boolean[] done = new boolean[n];
		for (int i = 0; i < n; i++)
		{
			Widget w = rows[i];
			if (w == null)
			{
				continue;
			}
			names[i] = w.getText();
			colors[i] = w.getTextColor();
			done[i] = colors[i] == COMPLETED_PAGE_COLOR;
		}

		// Desired display order: pending pages first, completed (green) last, each group stable.
		int[] perm = new int[n];
		int p = 0;
		for (int i = 0; i < n; i++)
		{
			if (!done[i])
			{
				perm[p++] = i;
			}
		}
		for (int i = 0; i < n; i++)
		{
			if (done[i])
			{
				perm[p++] = i;
			}
		}

		// Relabel each slot in place to show the page that belongs there (text + colour).
		for (int slot = 0; slot < n; slot++)
		{
			Widget w = rows[slot];
			int src = perm[slot];
			if (w == null || names[src] == null)
			{
				continue;
			}
			w.setText(names[src]);
			w.setTextColor(colors[src]);
		}

		pageNaturalText = names;
		pageNaturalColor = colors;
		pageListChild = child;
		pagePerm = perm; // published last; read by onMenuOptionClicked
	}

	private void restorePages()
	{
		if (pageListChild >= 0 && pageNaturalText != null)
		{
			Widget list = client.getWidget(COLLECTION_LOG_GROUP, pageListChild);
			Widget[] rows = list == null ? null : list.getDynamicChildren();
			if (rows != null)
			{
				int n = Math.min(rows.length, pageNaturalText.length);
				for (int i = 0; i < n; i++)
				{
					if (rows[i] != null && pageNaturalText[i] != null)
					{
						rows[i].setText(pageNaturalText[i]);
						rows[i].setTextColor(pageNaturalColor[i]);
					}
				}
			}
		}
		clearPageState();
	}

	private void clearPageState()
	{
		pagePerm = null;
		pageNaturalText = null;
		pageNaturalColor = null;
		pageListChild = -1;
	}

	/** The visible tab's category text layer, or -1 if the log isn't on a category tab. */
	private int activeCategoryListChild()
	{
		for (int child : CATEGORY_TEXT_CHILDREN)
		{
			Widget w = client.getWidget(COLLECTION_LOG_GROUP, child);
			if (w == null || w.isHidden())
			{
				continue;
			}
			Widget[] rows = w.getDynamicChildren();
			if (rows != null && rows.length >= 2)
			{
				return child;
			}
		}
		return -1;
	}

	// --- Items: physically reorder the icon grid by permuting them among their own cells. ---

	/**
	 * Reorders (or restores) the rows of one scrollable container by permuting them among the cells
	 * they already occupy. Extent is preserved, so scroll geometry is untouched. Used for the item
	 * grid (icons have no navigation click, so moving them is safe).
	 */
	private void layout(int containerChild, Predicate<Widget> isRow, Predicate<Widget> isPending, boolean restore)
	{
		Widget container = client.getWidget(COLLECTION_LOG_GROUP, containerChild);
		if (container == null || container.isHidden())
		{
			return;
		}
		Widget[] children = container.getDynamicChildren();
		if (children == null)
		{
			return;
		}

		List<Widget> natural = new ArrayList<>();
		for (Widget w : children)
		{
			if (w != null && isRow.test(w))
			{
				natural.add(w);
			}
		}
		if (natural.size() < 2)
		{
			return;
		}
		List<Widget> current = new ArrayList<>(natural);
		current.sort(BY_POSITION);
		List<int[]> slots = new ArrayList<>(current.size());
		for (Widget w : current)
		{
			slots.add(new int[]{w.getOriginalX(), w.getOriginalY()});
		}

		List<Widget> desired;
		if (restore)
		{
			desired = natural;
		}
		else
		{
			desired = new ArrayList<>(current.size());
			for (Widget w : current)
			{
				if (isPending.test(w))
				{
					desired.add(w);
				}
			}
			for (Widget w : current)
			{
				if (!isPending.test(w))
				{
					desired.add(w);
				}
			}
		}

		if (desired.equals(current))
		{
			return;
		}

		int n = Math.min(desired.size(), slots.size());
		for (int i = 0; i < n; i++)
		{
			Widget w = desired.get(i);
			int[] slot = slots.get(i);
			w.setOriginalX(slot[0]);
			w.setOriginalY(slot[1]);
			w.revalidate();
		}
	}

	// --- Combat Achievements: move whole boss cells (bosses with tasks left first). ---

	/**
	 * Reorders (or restores) the Combat Achievements boss grid so bosses that still have tasks left
	 * show first and fully-completed ("green") bosses drop to the bottom. Nothing is hidden.
	 *
	 * <p>{@link #layout} can't be reused here. It permutes one layer's children among the slots that
	 * same layer occupies, which needs one child per slot; a boss cell is stacked out of nine layers
	 * and one of them ({@code BOSSES_PROGRESS} 716:19) only gets a bar for bosses that have tasks, so
	 * its children aren't 1:1 with the boss. Instead we move <b>whole cells</b>: each part is matched
	 * to a cell by its own position and translated by the distance between that cell and its
	 * destination, which works for any number of parts per cell.
	 *
	 * <p>Matching by position is exact because every part of a cell is drawn inside that cell
	 * (145x88) while cells are pitched further apart than that (150x93) — so relative to the grid
	 * origin (the smallest position anything is drawn at, since row 0 and column 0 are always
	 * occupied) a part's column is {@code floorDiv(x - baseX, pitchX)} whichever layer it came from.
	 *
	 * <p>Everything is re-derived from the widgets' current positions on every pass, so re-applying
	 * to an already-reordered grid is a no-op, and restoring needs no snapshot: however far we moved
	 * them, {@code getDynamicChildren()} still hands the labels back in creation (natural) order, so
	 * restoring is this same walk with the natural order as its target.
	 *
	 * <p>Clicks need no remapping here (unlike the collection log's categories): the draw proc bakes
	 * each boss's own index into that cell's onOp args, so a moved cell still opens its own boss.
	 * The reordering is a permutation of the cells the grid already occupies, so its extent — and
	 * with it the scroll geometry — never changes.
	 */
	private void layoutCaBosses(boolean restore)
	{
		Widget list = client.getWidget(CA_BOSSES_GROUP, CA_BOSSES_LIST_CHILD);
		if (list == null || list.isHidden())
		{
			return;
		}
		Widget nameLayer = client.getWidget(CA_BOSSES_GROUP, CA_BOSSES_NAME_CHILD);
		Widget[] labels = nameLayer == null ? null : nameLayer.getDynamicChildren();
		if (labels == null || labels.length < 2)
		{
			return;
		}
		for (Widget label : labels)
		{
			if (label == null)
			{
				// A gap in the anchor layer would lose the cell -> boss mapping; leave the grid alone.
				return;
			}
		}
		int n = labels.length;

		// Every layer holding per-boss parts, plus the grid origin: the top-left of cell 0, which is
		// the smallest position anything is drawn at.
		List<Widget[]> layers = new ArrayList<>(CA_BOSSES_CELL_CHILDREN.length);
		int baseX = Integer.MAX_VALUE;
		int baseY = Integer.MAX_VALUE;
		for (int child : CA_BOSSES_CELL_CHILDREN)
		{
			Widget layer = client.getWidget(CA_BOSSES_GROUP, child);
			Widget[] parts = layer == null ? null : layer.getDynamicChildren();
			if (parts == null || parts.length == 0)
			{
				continue;
			}
			layers.add(parts);
			for (Widget part : parts)
			{
				if (part != null)
				{
					baseX = Math.min(baseX, part.getOriginalX());
					baseY = Math.min(baseY, part.getOriginalY());
				}
			}
		}
		if (layers.isEmpty())
		{
			return;
		}

		// The cells in reading order, and which of the game's labels currently sits in each. Their
		// positions are snapshotted here, before anything moves, because they're what the
		// translation vectors are measured from.
		Integer[] cellOwner = new Integer[n];
		for (int boss = 0; boss < n; boss++)
		{
			cellOwner[boss] = boss;
		}
		Arrays.sort(cellOwner, (a, b) -> BY_POSITION.compare(labels[a], labels[b]));

		int[] cellIn = new int[n];
		int[] cellX = new int[n];
		int[] cellY = new int[n];
		for (int cell = 0; cell < n; cell++)
		{
			int boss = cellOwner[cell];
			cellIn[boss] = cell;
			cellX[cell] = labels[boss].getOriginalX();
			cellY[cell] = labels[boss].getOriginalY();
		}

		// Grid spacing read off the labels rather than hardcoded, so an in-game layout tweak doesn't
		// need a plugin change; the column count comes from how far right the labels actually reach.
		int pitchX = pitch(labels, true, CA_CELL_PITCH_X);
		int pitchY = pitch(labels, false, CA_CELL_PITCH_Y);
		int columns = 1;
		for (int cell = 0; cell < n; cell++)
		{
			columns = Math.max(columns, Math.floorDiv(cellX[cell] - baseX, pitchX) + 1);
		}
		int[] grid = {baseX, baseY, pitchX, pitchY, columns};

		// Sanity check before touching anything: running the labels' own positions back through the
		// arithmetic has to reproduce the reading order exactly, or the grid isn't what we think.
		for (int cell = 0; cell < n; cell++)
		{
			if (cellIndex(grid, cellX[cell], cellY[cell]) != cell)
			{
				log.debug("CA boss list isn't a {}-column {}x{} grid; leaving it alone", columns, pitchX, pitchY);
				return;
			}
		}

		// Where each boss belongs: bosses with tasks left first, completed (green) ones after, both
		// groups in the game's natural order. Restoring wants that natural order itself. Completion
		// is read by creation index, which moving parts around never touches — that's what makes
		// re-applying to an already-reordered grid come out as a no-op.
		int[] target = new int[n];
		int next = 0;
		for (int boss = 0; boss < n; boss++)
		{
			if (restore || labels[boss].getTextColor() != COMPLETED_PAGE_COLOR)
			{
				target[next++] = boss;
			}
		}
		if (!restore)
		{
			for (int boss = 0; boss < n; boss++)
			{
				if (labels[boss].getTextColor() == COMPLETED_PAGE_COLOR)
				{
					target[next++] = boss;
				}
			}
		}

		int[] moveTo = new int[n];
		boolean moves = false;
		for (int cell = 0; cell < n; cell++)
		{
			int from = cellIn[target[cell]];
			moveTo[from] = cell;
			moves |= from != cell;
		}
		if (!moves)
		{
			return;
		}

		// Plan every part's new position first: if one of them doesn't land in a cell we leave the
		// whole grid untouched rather than scattering half of it.
		List<Widget> moving = new ArrayList<>();
		List<int[]> positions = new ArrayList<>();
		for (Widget[] parts : layers)
		{
			for (Widget part : parts)
			{
				if (part == null)
				{
					continue;
				}
				int from = cellIndex(grid, part.getOriginalX(), part.getOriginalY());
				if (from < 0 || from >= n)
				{
					log.debug("CA boss part at {},{} isn't in a cell; leaving the grid alone",
						part.getOriginalX(), part.getOriginalY());
					return;
				}
				int to = moveTo[from];
				if (to == from)
				{
					continue;
				}
				moving.add(part);
				positions.add(new int[]{
					part.getOriginalX() + cellX[to] - cellX[from],
					part.getOriginalY() + cellY[to] - cellY[from],
				});
			}
		}

		for (int i = 0; i < moving.size(); i++)
		{
			Widget part = moving.get(i);
			int[] pos = positions.get(i);
			part.setOriginalX(pos[0]);
			part.setOriginalY(pos[1]);
			revalidateDeep(part);
		}
	}

	/**
	 * The reading-order index of the grid cell a part drawn at {@code x,y} belongs to, or -1 if it
	 * isn't in one. {@code grid} is {@code {baseX, baseY, pitchX, pitchY, columns}}. Parts are
	 * matched to cells by position because a cell is stacked out of several layers with differing
	 * child counts, so a part's own index says nothing about which boss it's drawn for.
	 */
	private static int cellIndex(int[] grid, int x, int y)
	{
		int column = Math.floorDiv(x - grid[0], grid[2]);
		int row = Math.floorDiv(y - grid[1], grid[3]);
		if (column < 0 || column >= grid[4] || row < 0)
		{
			return -1;
		}
		return row * grid[4] + column;
	}

	/**
	 * The distance between neighbouring cells, measured as the smallest gap between any two anchors.
	 * Falls back to the draw proc's own spacing when the grid is a single column/row and there's no
	 * gap to measure — in which case nothing moves along that axis anyway.
	 */
	private static int pitch(Widget[] anchors, boolean horizontal, int fallback)
	{
		int best = 0;
		for (Widget a : anchors)
		{
			for (Widget b : anchors)
			{
				int gap = horizontal
					? a.getOriginalX() - b.getOriginalX()
					: a.getOriginalY() - b.getOriginalY();
				if (gap > 0 && (best == 0 || gap < best))
				{
					best = gap;
				}
			}
		}
		return best > 0 ? best : fallback;
	}

	/** Recomputes a moved part's geometry, and anything nested in it (e.g. a progress bar's segments). */
	private static void revalidateDeep(Widget part)
	{
		part.revalidate();
		revalidateDeep(part.getDynamicChildren());
		revalidateDeep(part.getStaticChildren());
		revalidateDeep(part.getNestedChildren());
	}

	private static void revalidateDeep(Widget[] children)
	{
		if (children == null)
		{
			return;
		}
		for (Widget child : children)
		{
			if (child != null)
			{
				revalidateDeep(child);
			}
		}
	}
}

